function stageFacultyLink(faculty,course){if(!faculty||!course)return;stagedAssignmentChanges=stagedAssignmentChanges.filter(x=>!(x.course===course&&x.type==='add'));stagedAssignmentChanges=stagedAssignmentChanges.filter(x=>!(x.faculty===faculty&&x.course===course&&x.type==='remove'));if(!assignmentLinks.some(x=>x[0]===faculty&&x[1]===course))stagedAssignmentChanges.push({type:'add',faculty,course});selectedFacultyNode='';document.querySelectorAll('.faculty-node.selected-node').forEach(n=>n.classList.remove('selected-node'));document.querySelector(`[data-course="${course}"]`)?.classList.add('staged-node');renderAssignmentLabels();drawAssignmentEdges()}
