const demoAccounts=[['student','Aarav Suresh','Student','aarav.suresh@kannuruniv.ac.in'],['teacher','Dr. Meera Nair','Course Teacher','meera.nair@kannuruniv.ac.in'],['teaching_staff','Anjali Menon','Teaching Staff','anjali.menon@kannuruniv.ac.in'],['hod','Dr. Ravi Kumar','Head of Department','ravi.kumar@kannuruniv.ac.in'],['director','Prof. S. Rajendran','Campus Director','director.tly@kannuruniv.ac.in'],['superadmin','Admin User','Super Admin','admin@kannuruniv.ac.in']];
let pendingRole='student';const consentedRoles=new Set();
