document.addEventListener('click',e=>{const more=e.target.closest('#moreNavButton');if(more){const menu=$('#moreNavMenu');menu.hidden=!menu.hidden;return}const dayFilter=e.target.closest('[data-day-filter]');if(dayFilter){document.querySelectorAll('[data-day-filter]').forEach(b=>b.classList.toggle('active',b===dayFilter));document.querySelectorAll('[data-day-row]').forEach(row=>row.hidden=dayFilter.dataset.dayFilter!=='all'&&row.dataset.dayRow!==dayFilter.dataset.dayFilter);return}const page=e.target.closest('[data-page]');if(page){active=page.dataset.page;render();return}const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action;if(a==='saveAssignments'){commitAssignmentChanges();showToast('Faculty assignments saved in this preview');return}else if(a==='discardAssignments'){discardAssignmentChanges();return}else if(a==='day')showToast('Day view selected');else if(a==='refresh')showToast('Sample HOD data refreshed');else if(a==='export')showToast('Sample Excel export prepared');else if(a==='submit'||a==='generate'||a==='signin'||a==='promote'||a==='allocate'||a==='unlock'||a==='delete'||a==='add'||a==='edit'||a==='assign'||a==='upload'||a==='remind'||a==='view'||a==='save'||a==='pause'||a==='copy'||a==='download'||a==='export'||a==='refresh'||a==='addTeacher'||a==='manageTeachers'||a==='refreshAssignments'||a==='teacherAttendance'||a==='teacherPdf'||a==='closeRegistration'||a==='runAllocation'||a==='rules'||a==='exportTimetable'||a==='publishTimetable')openModal(a,action.dataset);else showToast(({saveWindow:'Registration deadline saved in this preview',promotionStart:'Promotion confirmation opened',promotionContinue:'Promotion confirmation opened',promotionCancel:'Promotion cancelled',attendance:'Attendance roster opened in sample mode',download:'Sample template is ready',remind:'Reminder preview created',copy:'Sample student list copied',pause:'Window setting preview opened',studyhub:'Study Hub link preview'})[a]||'Sample action complete');return}if(e.target.closest('#noticeButton')){if(roleKey==='student'){active='notifications';render()}else showToast('No new notifications in this workspace')}});
$('#modalClose').addEventListener('click',closeModal);$('#modalCancel').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});$('#modalConfirm').addEventListener('click',()=>{const a=$('#modalConfirm').dataset.action;closeModal();if(a==='logout'){signOut();return}showToast(({signin:'Campus sign-in recorded in this preview',promote:'Promotion preview complete',unlock:'Late-entry unlock staged in this preview',delete:'Removal confirmation recorded in this preview',submit:'Course registration saved as a draft',generate:'Timetable draft generated',allocate:'Allocation preview complete',remind:'Reminder preview prepared'})[a]||'Saved in this preview')});
